// Smoke test of the built bundle in jsdom, with a page generated by PHP: node test/smoke.mjs
import { JSDOM, VirtualConsole } from 'jsdom';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const html = execFileSync('php', ['test/page.php'], { encoding: 'utf8' }).replace(/^[^<]*/, '');
const errors = [];
const virtualConsole = new VirtualConsole();
virtualConsole.on('jsdomError', (e) => errors.push(e.message));

const dom = new JSDOM(html, {
  url: pathToFileURL(`${process.cwd()}/test/page.html`).href,
  runScripts: 'dangerously',
  resources: 'usable',
  pretendToBeVisual: true,
  virtualConsole,
  beforeParse(window) {
    window.matchMedia = window.matchMedia || (() => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} }));
    window.ResizeObserver = window.ResizeObserver || class { observe() {} unobserve() {} disconnect() {} };
    window.scrollTo = () => {};
    Object.defineProperty(window.screen, 'orientation', { value: { type: 'landscape-primary', angle: 0, addEventListener() {}, removeEventListener() {} } });
  },
});
const { window } = dom;
await new Promise((resolve) => window.addEventListener('load', resolve));
const tick = (ms = 80) => new Promise((resolve) => setTimeout(resolve, ms));
await tick(200);

let failed = 0;
function check(name, ok, detail = '') {
  console.log(`${ok ? '  ok  ' : '  FALLA'} ${name}${ok || !detail ? '' : ' → ' + detail}`);
  if (!ok) failed++;
}

if (errors.length) console.log('errores:', errors.join(' | '));
const doc = window.document;
const app = doc.querySelector('#uk-app');
check('no expone window.Vue', window.Vue === undefined);
check('se monta el layout de Quasar', !!app.querySelector('.q-layout.uk-layout'));
check('encabezado con marca y usuario', app.querySelector('.uk-header .uk-brand-title')?.textContent === 'Intranet'
  && app.querySelector('.uk-theme-user')?.textContent === 'Ivan Zea');
check('enlace del encabezado como q-btn', !!app.querySelector('a.q-btn[href="soporte.php"]'));
check('menú lateral con su opción activa', app.querySelector('.uk-left .uk-menu-active')?.textContent.includes('Picking'));
check('alerta y tarjeta', !!app.querySelector('.q-banner.uk-alert--warning') && app.querySelector('.uk-card .uk-card-title')?.textContent === 'Viajes');

const cell = app.querySelector('#legacy-cell');
check('el HTML heredado se movió al layout', !!cell && !!cell.closest('.uk-raw'));
check('el contenedor oculto quedó vacío', doc.querySelector('#uk-raw-1')?.childNodes.length === 0);
cell?.dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
check('su script conservó el manejador de eventos', cell?.textContent === 'con clic', cell?.textContent);

const tabs = [...app.querySelectorAll('.q-tab')];
check('pestañas de Quasar', tabs.length === 2);
tabs[0].dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
await tick();
check('cambiar de pestaña muestra el otro panel', app.querySelector('.uk-tab-panel')?.textContent.includes('Panel nuevo'), app.querySelector('.q-tab-panels')?.textContent);
tabs[1].dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
await tick();
const back = app.querySelector('#legacy-cell');
check('al volver, el HTML heredado sigue ahí (no se pierde)', !!back && back.textContent === 'con clic', back?.textContent);

const searchInput = app.querySelector('.uk-left .uk-menu-search input');
const typeSearch = async (text) => { searchInput.value = text; searchInput.dispatchEvent(new window.Event('input', { bubbles: true })); await tick(); };
const menuText = () => app.querySelector('.uk-left .uk-menu')?.textContent || '';
check('buscador en el menú', !!searchInput && searchInput.getAttribute('placeholder') === 'Buscar opción');
await typeSearch('pick');
check('el buscador encuentra la opción hija', menuText().includes('Picking') && menuText().includes('Logística') && !menuText().includes('Inicio'), menuText());
await typeSearch('ick');
check('solo coincide con el inicio de las palabras', !menuText().includes('Picking') && !!app.querySelector('.uk-left .uk-menu-empty'), menuText());
await typeSearch('LOGISTICA');
check('sin distinguir mayúsculas ni tildes', menuText().includes('Logística') && !menuText().includes('Inicio'), menuText());
await typeSearch('zzz');
check('sin coincidencias muestra el aviso', !!app.querySelector('.uk-left .uk-menu-empty'), menuText());
await typeSearch('');
check('al borrar vuelve el menú completo', menuText().includes('Inicio') && menuText().includes('Picking'), menuText());

const dismissNotice=window.UiKitQuasar.notify('<b id="feedback-html">Mensaje de prueba</b>','info');
await tick();
check('notificacion muestra texto sin interpretar HTML',!doc.getElementById('feedback-html')&&doc.body.textContent.includes('<b id="feedback-html">Mensaje de prueba</b>'));
dismissNotice();
const cancelled=window.UiKitQuasar.confirm('Confirmacion de prueba');
await tick();
[...doc.querySelectorAll('.q-dialog button')].find(b=>b.textContent.trim()==='Cancelar').click();
check('confirmacion cancelada devuelve false',await cancelled===false);
await tick(250);
const accepted=window.UiKitQuasar.confirm('Confirmacion de prueba');
await tick();
[...doc.querySelectorAll('.q-dialog button')].find(b=>b.textContent.trim()==='Aceptar').click();
check('confirmacion aceptada devuelve true',await accepted===true);
await tick(250);
const alert=window.UiKitQuasar.alert('Aviso de prueba');
await tick();
[...doc.querySelectorAll('.q-dialog button')].find(b=>b.textContent.trim()==='Aceptar').click();
await alert;
check('aviso se cierra mediante el dialogo del kit',true);
check('sin errores de JavaScript', errors.length === 0, errors.join(' | '));
console.log(failed === 0 ? '\nsmoke OK' : `\n${failed} fallas`);
process.exit(failed === 0 ? 0 : 1);
